entries[422837] = { ["name"] = "Apocalypse Roar", ["text"] = "4.8 sec cast\nFyrakk unleashes an incinerating roar, inflicting 1560347 Shadowflame damage to all players and pushing them away.\n\nPlayers suffer an additional 101533 Shadowflame damage every 1 sec for 12 sec." }
