entries[422850] = { ["name"] = "Death Knight Blood 10.2 Class Set 2pc", ["text"] = "Consuming Runic Power has a chance to cause your next Heart Strike to apply Ashen Decay, reducing damage dealt to you by 10% and increasing your damage dealt to afflicted targets by 20% for 8 sec." }
entries[422851] = { ["name"] = "Death Knight Blood 10.2 Class Set 4pc", ["text"] = "Soul Reaper's execute damage and Abomination Limb's damage applies Ashen Decay to enemy targets, and Heart Strike and Blood Boil's direct damage extends Ashen Decay by 1.0 sec." }
entries[422852] = { ["name"] = "Death Knight Frost 10.2 Class Set 2pc", ["text"] = "Chill Streak's range is increased by 4 yds and can bounce off of you. Each time Chill Streak bounces your damage is increased by 4% for 12 sec, stacking up to 5 times." }
entries[422853] = { ["name"] = "Death Knight Frost 10.2 Class Set 4pc", ["text"] = "Chill Streak can bounce 3 additional times and each time it bounces, you have a 35% chance to gain a Rune, reduce Chill Streak cooldown by 5 sec, or reduce the cooldown of Empower Rune Weapon by 6 sec." }
entries[422854] = { ["name"] = "Death Knight Unholy 10.2 Class Set 2pc", ["text"] = "Apocalypse summons an additional Magus of the Dead. Your Magus of the Dead Shadow Bolt now fires a volley of Shadow Bolts at up to 4 nearby enemies." }
entries[422855] = { ["name"] = "Death Knight Unholy 10.2 Class Set 4pc", ["text"] = "Each Rune you spend increases the duration of your active Magi by 0.5 sec and your Magi will now also cast Amplify Damage, increasing the damage you deal by 5% for 10 sec." }
entries[422856] = { ["name"] = "Rime" }
entries[422857] = { ["name"] = "Demon Hunter Havoc 10.2 Class Set 2pc", ["text"] = "Blade Dance automatically triggers Throw Glaive on your primary target for 100% damage and each slash has a 50% chance to Throw Glaive an enemy for 35% damage." }
entries[422858] = { ["name"] = "Pip's Emerald Friendship Badge", ["text"] = "Approximately 2 procs per minute\nJoin the Dream Team, gaining ( 266 / 12) of Pip's Mastery, Urctos's Versatility, or Aerwynn's Critical Strike based on your current Best Friend.\n\nYour spells and abilities have a chance to tag in a random new Best Friend, granting you their passive bonus and empowering it to 266 before diminishing over 12 sec.\n(12s cooldown)" }
entries[422859] = { ["name"] = "Demon Hunter Havoc 10.2 Class Set 4pc", ["text"] = "Throw Glaive reduces the remaining cooldown of The Hunt by 2.0 sec, and The Hunt's damage over time effect lasts 6 sec longer." }
entries[422860] = { ["name"] = "Demon Hunter Vengeance 10.2 Class Set 2pc", ["text"] = "When you attack a target afflicted by Sigil of Flame, your damage and healing are increased by 2% and your Stamina is increased by 2% for 8 sec, stacking up to 5.\n(750ms cooldown)" }
entries[422861] = { ["name"] = "Demon Hunter Vengeance 10.2 Class Set 4pc", ["text"] = "Sigil of Flame's periodic damage has a chance to flare up, shattering an additional Soul Fragment from a target and dealing (60.72% of Attack Power) additional damage. Each 40 Fury you spend reduces its cooldown by 1.0 sec." }
entries[422862] = { ["name"] = "Druid Balance 10.2 Class Set 2pc", ["text"] = "When Eclipse ends or when you enter combat, enter a Dreamstate, reducing the cast time of your next 2 Starfires or Wraths by 40% and increasing their damage by 100%." }
entries[422863] = { ["name"] = "Druid Balance 10.2 Class Set 4pc", ["text"] = "Starsurge or Starfall increase your current Eclipse's Arcane or Nature damage bonus by an additional 2%, up to 10%." }
entries[422864] = { ["name"] = "Druid Guardian 10.2 Class Set 2pc", ["text"] = "Rage you spend during Rage of the Sleeper fuel the growth of Dream Thorns, which wreath you in their protection after Rage of the Sleeper expires, absorbing 25% of damage dealt to you while the thorns remain, up to (660 / 100 * Attack Power) per 20 Rage spent." }
entries[422865] = { ["name"] = "Druid Guardian 10.2 Class Set 4pc", ["text"] = "Each 40 Rage you spend while Rage of the Sleeper is active extends its duration by 1.0 sec, up to 5.0. Your Dream Thorns become Blazing Thorns, causing 100% of damage absorbed to be reflected at the attacker." }
entries[422866] = { ["name"] = "Druid Restoration 10.2 Class Set 2pc", ["text"] = "You and your Grove Guardian's Nourishes now heal 2 additional allies within 40 yds at 40% effectiveness." }
entries[422867] = { ["name"] = "Druid Restoration 10.2 Class Set 4pc", ["text"] = "Consuming Clearcasting now causes your Regrowth to also cast Nourish onto a nearby injured ally at 200% effectiveness, preferring those with your heal over time effects." }
entries[422868] = { ["name"] = "Evoker Augmentation 10.2 Class Set 2pc", ["text"] = "Every third Prescience lasts 100% longer." }
entries[422869] = { ["name"] = "Evoker Augmentation 10.2 Class Set 4pc", ["text"] = "Casting Prescience enhances your next Eruption with smaller fissures for each Prescience you have active, each dealing (110% of Spell Power) damage and extending Ebon Might by 0.2 sec." }
entries[422870] = { ["name"] = "Evoker Devastation 10.2 Class Set 2pc", ["text"] = "While Dragonrage is active you gain Emerald Trance every 6 sec, increasing your damage done by 5%, stacking up to 5 times.\n(Proc chance: 15%, 500ms cooldown)" }
entries[422871] = { ["name"] = "Evoker Devastation 10.2 Class Set 4pc", ["text"] = "When Dragonrage ends, Emerald Trance persists for 5 sec per stack and grants you Essence Burst every 5 sec." }
entries[422872] = { ["name"] = "Evoker Preservation 10.2 Class Set 2pc", ["text"] = "Empower spells cast up to 3 Living Flames at enemies or allies struck at 50% effectiveness." }
entries[422873] = { ["name"] = "Evoker Preservation 10.2 Class Set 4pc", ["text"] = "Living Flame has a chance to apply Echo at 70% effectiveness on allies healed, or a nearby ally who doesn't already have Echo.\n(Proc chance: 33%)" }
entries[422874] = { ["name"] = "Hunter Beast Mastery 10.2 Class Set 2pc", ["text"] = "Bestial Wrath summons a Dire Beast for 10 sec.\n(1s cooldown)" }
entries[422875] = { ["name"] = "Hunter Beast Mastery 10.2 Class Set 4pc", ["text"] = "Your most recently summoned Dire Beast now obeys your Kill Command and can benefit from Beast Cleave." }
entries[422876] = { ["name"] = "Hunter Marksmanship 10.2 Class Set 2pc", ["text"] = "Rapid Fire rains a Volley at the target's location for 2 sec." }
entries[422877] = { ["name"] = "Hunter Marksmanship 10.2 Class Set 4pc", ["text"] = "Legacy of the Windrunners now has a 15% chance to fire a Wind Arrow at targets damaged by Volley.\n(Proc chance: 15%)" }
entries[422878] = { ["name"] = "Hunter Survival 10.2 Class Set 2pc", ["text"] = "Fury of the Eagle increases you and your pet's critical strike chance by 15% and critical damage dealt by 15% for 12 sec." }
entries[422879] = { ["name"] = "Hunter Survival 10.2 Class Set 4pc", ["text"] = "Fury of the Eagle throws a free Wildfire Bomb at your current target at 100% effectiveness, causes your next Wildfire Bomb to not incur a cooldown, and increases the damage Wildfire Bomb deals to your primary target by 40% for 12 sec." }
entries[422880] = { ["name"] = "Mage Arcane 10.2 Class Set 2pc", ["text"] = "Consuming Clearcasting grants increased spell damage by 2% for 20 sec, stacking up to 10%." }
entries[422881] = { ["name"] = "Mage Arcane 10.2 Class Set 4pc", ["text"] = "After consuming Clearcasting 3 times, your next Arcane Missiles consumes Arcane Battery, dealing 150% increased damage to your primary target and fires at up to 4 nearby enemies dealing 100% increased damage." }
entries[422882] = { ["name"] = "Mage Fire 10.2 Class Set 2pc", ["text"] = "When Pyroblast and Flamestrike critically strike you gain Searing Rage, increasing your critical strike damage by 4% for 12 sec, stacking up to 20%." }
entries[422883] = { ["name"] = "Mage Fire 10.2 Class Set 4pc", ["text"] = "Activating Combustion increases the critical strike damage bonus of Searing Rage by 150% for 12 sec." }
entries[422884] = { ["name"] = "Mage Frost 10.2 Class Set 2pc", ["text"] = "Glacial Spike damage increased by 16% and it explodes when it Shatters a frozen target, dealing 15% of its damage dealt to nearby enemies. Deals reduced damage beyond 8 targets." }
entries[422885] = { ["name"] = "Mage Frost 10.2 Class Set 4pc", ["text"] = "Casting Glacial Spike has a 40% chance to trigger Brain Freeze." }
entries[422886] = { ["name"] = "Monk Brewmaster 10.2 Class Set 2pc", ["text"] = "Breath of Fire deals 40% bonus damage as Shadowflame and causes you to heal for 50% of your Fire damage dealt." }
entries[422887] = { ["name"] = "Monk Brewmaster 10.2 Class Set 4pc", ["text"] = "Your attacks against targets afflicted by Breath of Fire have a chance to deal 15% extra damage as Shadowflame, and each Celestial Brew also grants a Stagger absorb for 100% of the Shadowflame damage you have dealt, causing damage delayed by Stagger to instead be prevented." }
entries[422889] = { ["name"] = "Monk Mistweaver 10.2 Class Set 2pc", ["text"] = "Renewing Mist applies Chi Harmony to its initial target, increasing their healing taken from you by 25% for 8 sec." }
entries[422890] = { ["name"] = "Monk Mistweaver 10.2 Class Set 4pc", ["text"] = "20% of all healing you do to targets with Chi Harmony is stored and then dispersed evenly among your allies with Renewing Mist when Chi Harmony fades or is refreshed." }
entries[422891] = { ["name"] = "Monk Windwalker 10.2 Class Set 2pc", ["text"] = "Approximately 2.5 procs per minute\nFree Spinning Crane Kicks grant Blackout Reinforcement, increasing the damage of your next Blackout Kick by 250%. Melee abilities have a chance to grant Blackout Reinforcement." }
entries[422892] = { ["name"] = "Monk Windwalker 10.2 Class Set 4pc", ["text"] = "Blackout Reinforcement empowered Blackout Kicks reduce the cooldown of Fists of Fury, Rising Sun Kick, Strike of the Windlord, and Whirling Dragon Punch by 3.0 sec.\nDamage of Fists of Fury, Rising Sun Kick, Strike of the Windlord, and Whirling Dragon Punch increased by 4%." }
entries[422893] = { ["name"] = "Paladin Holy 10.2 Class Set 2pc", ["text"] = "When Glimmer of Light dissipates or is refreshed, it creates a Holy Reverberation on its target to heal an ally for (108% of Spell Power) or damage an enemy for (96% of Spell Power) over 8 sec. Multiple Holy Reverberations may overlap, up to 6 times." }
entries[422894] = { ["name"] = "Paladin Holy 10.2 Class Set 4pc", ["text"] = "Daybreak now increases Haste by 25% for 6 sec and its cooldown is reduced by 15 sec.\n(250ms cooldown)" }
entries[422895] = { ["name"] = "Paladin Protection 10.2 Class Set 2pc", ["text"] = "Judgment grants a stack of Sanctification, reducing your damage taken by 2.0% per stack. Upon reaching 5 stacks, your next cast of Consecration is empowered, increasing its damage and healing by 200% and its radius by 30%. Sanctification's stacks are reset when your empowered Consecration ends." }
entries[422896] = { ["name"] = "Paladin Protection 10.2 Class Set 4pc", ["text"] = "While you are within an empowered Consecration, your abilities have a chance to deal 40% bonus damage or healing as Fire." }
entries[422899] = { ["name"] = "Priest Discipline 10.2 Class Set 2pc", ["text"] = "Smite and Penance damage increased by 20% and Smite extends the duration of an active Atonement by 2.0 sec." }
entries[422900] = { ["name"] = "Priest Discipline 10.2 Class Set 4pc", ["text"] = "Smite has a 100% chance to cast an additional time during Shadow Covenant, dealing (80% of Spell Power) Shadow damage." }
entries[422901] = { ["name"] = "Priest Holy 10.2 Class Set 2pc", ["text"] = "Holy Word: Serenity applies 18 sec of Renew to its target. Holy Word: Sanctify applies 6 sec of Renew to allies it heals." }
entries[422902] = { ["name"] = "Priest Holy 10.2 Class Set 4pc", ["text"] = "Renew's healing has a chance to cause your next Holy Word: Sanctify or Holy Word: Serenity to not consume a charge when cast and cost 50% less Mana, accumulating up to 2 charges." }
entries[422903] = { ["name"] = "Priest Shadow 10.2 Class Set 2pc", ["text"] = "Shadow Word: Death triggers 2 additional times at 15% effectiveness. Triggers again 1 additional time at 15% effectiveness if Deathspeaker is active or your target is below (85% of Spell Power) % health." }
entries[422904] = { ["name"] = "Priest Shadow 10.2 Class Set 4pc", ["text"] = "Each time you take damage from Shadow Word: Death, gain a stack of Death's Torment, increasing the initial damage of your next cast of Shadow Word: Pain by 225% or increasing the damage of your next Shadow Crash by 50%, stacking up to 12 times." }
entries[422905] = { ["name"] = "Rogue Assassination 10.2 Class Set 2pc", ["text"] = "Each 10 energy you spend grants Natureblight, granting 1.0% attack speed and 1.0% Nature Damage for 6 sec. Multiple instances of Natureblight may overlap, up to 12." }
entries[422906] = { ["name"] = "Rogue Assassination 10.2 Class Set 4pc", ["text"] = "Envenom additionally empowers itself, causing an Envenomous Explosion dealing (90% of Attack Power) Nature damage to all nearby enemies when cast with Envenom active. Deals reduced damage beyond 5 targets. If Envenomous Explosion deals damage to a single target, it is increased by 30%." }
entries[422907] = { ["name"] = "Rogue Outlaw 10.2 Class Set 2pc", ["text"] = "Sinister Strike has an additional 10% chance of striking an additional time." }
entries[422908] = { ["name"] = "Rogue Outlaw 10.2 Class Set 4pc", ["text"] = "Roll the Bones additionally refreshes a random Roll the Bones combat enhancement buff you currently possess." }
entries[422909] = { ["name"] = "Rogue Subtlety 10.2 Class Set 4pc", ["text"] = "Your shadow clones deal 20% increased damage with all attacks and grant you 2 combo points per clone when summoned." }
entries[422910] = { ["name"] = "Rogue Subtlety 10.2 Class Set 2pc", ["text"] = "Using Eviscerate, Rupture, or Black Powder has a chance to summon a shadow clone to echo your finishing move for 70% additional Shadow damage." }
entries[422911] = { ["name"] = "Shaman Elemental 10.2 Class Set 2pc", ["text"] = "Primordial Wave also casts an Elemental Blast at the target at 70% effectiveness, and grants you all three Elemental Blast bonus effects for 10.0 sec." }
entries[422912] = { ["name"] = "Shaman Elemental 10.2 Class Set 4pc", ["text"] = "Lava Burst burns your target for 10% additional damage over 4 sec, and after consuming Primordial Wave, your next 2 casts of Lava Burst to also hit up to 3 additional targets affected by your Flame Shock for 65% of normal damage." }
entries[422913] = { ["name"] = "Shaman Enhancement 10.2 Class Set 2pc", ["text"] = "Primordial Wave summons a Lightning Feral Spirit that increases your Nature damage dealt by 20% for 15 sec." }
entries[422914] = { ["name"] = "Shaman Enhancement 10.2 Class Set 4pc", ["text"] = "Summoning a Feral Spirit reduces the cooldown of Primordial Wave by 7.0 sec." }
entries[422915] = { ["name"] = "Shaman Restoration 10.2 Class Set 2pc", ["text"] = "Chain Heal, Healing Surge, and Healing Wave mark their initial target with a Tidal Reservoir, causing them to receive 15% of all Riptide healing you deal for 15 sec." }
entries[422916] = { ["name"] = "Shaman Restoration 10.2 Class Set 4pc", ["text"] = "Riptide's healing is increased by 25%. If Riptide is active on the same target as Tidal Reservoir, its heal over time effect has a 6% chance to create a new Riptide on a nearby ally." }
entries[422917] = { ["name"] = "Warlock Affliction 10.2 Class Set 2pc", ["text"] = "Soul Rot deals 15% increased damage and lasts an additional 4 sec." }
entries[422918] = { ["name"] = "Warlock Affliction 10.2 Class Set 4pc", ["text"] = "Soul Rot grants 3 Umbrafire Kindling which increase the damage of your next Malefic Rapture to deal 50% or your next Seed of Corruption by 60%. Additionally, Umbrafire Kindling causes Malefic Rapture to extend the duration of your damage over time effects and Haunt by 2 sec." }
entries[422919] = { ["name"] = "Warlock Demonology 10.2 Class Set 2pc", ["text"] = "Consuming a Demonic Core applies a Doom Brand that explodes after 20 sec, dealing (268.747% of Spell Power) Shadow damage to nearby enemies or [(268.747% of Spell Power) * (2.25)] Shadow damage to a single enemy. Hand of Gul'dan reduces the duration of your Doom Brands by 1 sec per Soul Shard spent." }
entries[422920] = { ["name"] = "Warlock Demonology 10.2 Class Set 4pc", ["text"] = "When Doom Brand is removed, you have a chance to summon a Doomfiend that casts 5 Doom Bolt Volleys before departing. Each Doom Bolt Volley deals [(1.553369999\n* (Spell Power) * 1 * (1 + Versatility)) * 1.169617819] Shadow damage to up to 4 enemies or [((1.553369999\n* (Spell Power) * 1 * (1 + Versatility)) * 1.169617819) * (2.1)] Shadow damage to a single enemy." }
entries[422921] = { ["name"] = "Warlock Destruction 10.2 Class Set 2pc", ["text"] = "Bolts from Dimensional Rifts now deal 25% of damage dealt to nearby enemies. Immolate periodic damage has a chance to grant a charge of Dimensional Rift." }
entries[422922] = { ["name"] = "Warlock Destruction 10.2 Class Set 4pc", ["text"] = "Dimensional Rift can now summon a powerful Flame Rift which blasts 20 Searing Bolts that deal (56.9622% of Spell Power) Fire damage and an additional (22.793% of Spell Power) Fire damage over 10 sec." }
entries[422923] = { ["name"] = "Warrior Arms 10.2 Class Set 2pc", ["text"] = "Approximately 2 procs per minute\nRend damage increased by 30% and Sudden Death can be triggered by Rend's bleed damage." }
entries[422924] = { ["name"] = "Warrior Arms 10.2 Class Set 4pc", ["text"] = "Sudden Death also makes your next Execute powerfully slam the ground, causing a Thunder Clap that deals 200% increased damage. In addition, the Execute target bleeds for 50% of Execute's damage over 5 sec. If this bleed is reapplied, remaining damage is added to the new bleed.\n(500ms cooldown)" }
entries[422925] = { ["name"] = "Warrior Fury 10.2 Class Set 2pc", ["text"] = "Odyn's Fury deals 50% increased damage and causes your next 3 Bloodthirsts to deal 150% additional damage and have 100% increased critical strike chance against its primary target." }
